import java.util.Scanner;

public class Main {
    static int m, n, p;
    static int[] dp = new int[505], cnt = new int[505], fac = new int[505], invfac = new int[505];
    static int[][] dp2 = new int[505][505], tot = new int[505][505], tmpArr = new int[505][505];
    static int[] sumCache = new int[505];

    static int mypow(int a, int b) {
        int ans = 1;
        while (b > 0) {
            if ((b & 1) == 1) ans = (int)((long)ans * a % p);
            a = (int)((long)a * a % p);
            b >>= 1;
        }
        return ans;
    }

    static int C(int n, int m) {
        return (int)((long)fac[n] * invfac[m] % p * invfac[n - m] % p);
    }

    static int sum(int x) {
        return (int)((long)x * (x + 1) / 2 % p);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        p = sc.nextInt();

        fac[0] = 1;
        for (int i = 1; i <= 500; i++) {
            fac[i] = (int)((long)fac[i - 1] * i % p);
        }
        invfac[500] = mypow(fac[500], p - 2);
        for (int i = 499; i >= 0; i--) {
            invfac[i] = (int)((long)invfac[i + 1] * (i + 1) % p);
        }

        cnt[0] = 1;
        dp[0] = 0;
        cnt[1] = 2;
        dp[1] = 0;

        for (int i = 2; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                int zh = C(i - 1, j - 1);
                int tmp = (int)((long)cnt[j - 1] * cnt[i - j] % p * zh % p);
                dp[i] = (int)((long)dp[i] + (long)tmp * sum(j - 1) + (long)zh * j % p * ((long)dp[j - 1] * cnt[i - j] % p + (long)dp[i - j] * cnt[j - 1] % p)) % p;
                cnt[i] = (int)((long)cnt[i] + (long)tmp * j) % p;
                dp[i] = (int)((long)dp[i] + (long)tmp * sum(i - j) + (long)zh * (i - j + 1) % p * ((long)dp[j - 1] * cnt[i - j] % p + (long)dp[i - j] * cnt[j - 1] % p)) % p;
                cnt[i] = (int)((long)cnt[i] + (long)tmp * (i - j + 1)) % p;
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp2[i][j] = 0;
                tot[i][j] = 0;
            }
        }
        dp2[0][0] = 0;
        tot[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(m, i); j++) {
                dp2[i][j] = dp2[i - 1][j];
                tot[i][j] = tot[i - 1][j];
                for (int k = 1; k <= j; k++) {
                    if (k < i) {
